func TestNoStackedCommentsRespectsInlineNoqa(t *testing.T) {
	config := DefaultConfig()
	config.Select = []string{"LEG043"}
	source := "# First comment.\n# Second comment. noqa: LEG043\n"
	assertScan(t, source, config, nil)
}

func TestNoStackedCommentsIgnoresNonComments(t *testing.T) {
	config := DefaultConfig()
	config.Select = []string{"LEG043"}
	source := `printf '%s\n' '# Quoted.'
# First comment.
cat <<'EOF'
# Heredoc payload.
EOF
# Second comment.
`
	assertScan(t, source, config, nil)
}

func TestNoStackedCommentsReportsEachAddition(t *testing.T) {
	config := DefaultConfig()
	config.Select = []string{"LEG043"}
	source := `# First comment.
# Second comment.
# Third comment.
`
	want := []expectedDiagnostic{
		{"LEG043", 2, 1, "Update or remove the adjacent comment instead of stacking another comment."},
		{"LEG043", 3, 1, "Update or remove the adjacent comment instead of stacking another comment."},
	}
	assertScan(t, source, config, want)
}

