func TestNoUnmatchedCommentsRejectsPartialIdentifiers(t *testing.T) {
	config := DefaultConfig()
	config.Select = []string{"LEG041"}
	config.CommentPrefixes = []string{"KEEP"}
	config.CommentSuffixes = []string{"@keep"}
	source := `


# KEEPING generated not@keep
`
	want := []expectedDiagnostic{
		{"LEG041", 4, 1, "Comment does not match a configured matcher, prefix identifier, or suffix identifier."},
	}
	assertScan(t, source, config, want)
}
